CREATE TABLE IF NOT EXISTS shop_warehouse(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,priority INT NOT NULL DEFAULT 100,enabled BOOLEAN NOT NULL DEFAULT TRUE);
INSERT IGNORE INTO shop_warehouse(id,name,priority) VALUES(1,'默认仓库',1);
CREATE TABLE IF NOT EXISTS shop_warehouse_stock(warehouse_id BIGINT NOT NULL,product_id BIGINT NOT NULL,channel CHAR(1) NOT NULL,available BIGINT NOT NULL DEFAULT 0,reserved BIGINT NOT NULL DEFAULT 0,quarantine BIGINT NOT NULL DEFAULT 0,damaged BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(warehouse_id,product_id,channel));
CREATE TABLE IF NOT EXISTS shop_warehouse_allocation(order_id BIGINT NOT NULL,product_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,channel CHAR(1) NOT NULL,reserved BIGINT NOT NULL DEFAULT 0,shipped BIGINT NOT NULL DEFAULT 0,released BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(order_id,product_id,warehouse_id));
CREATE TABLE IF NOT EXISTS shop_warehouse_movement(id BIGINT PRIMARY KEY AUTO_INCREMENT,warehouse_id BIGINT NOT NULL,product_id BIGINT NOT NULL,channel CHAR(1) NOT NULL,kind VARCHAR(30) NOT NULL,quantity BIGINT NOT NULL,reference_key VARCHAR(100) NOT NULL,note VARCHAR(300) NOT NULL,operator_name VARCHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shop_warehouse_return(case_id BIGINT NOT NULL,product_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,channel CHAR(1) NOT NULL,quantity BIGINT NOT NULL,accepted BIGINT NOT NULL DEFAULT 0,damaged BIGINT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'pending',PRIMARY KEY(case_id,product_id));
CREATE TABLE IF NOT EXISTS shop_warehouse_plan(order_id BIGINT PRIMARY KEY,warehouse_id BIGINT NOT NULL DEFAULT 0);
INSERT IGNORE INTO shop_config(config_key,content) SELECT 'warehouse-migration',JSON_OBJECT('legacyMax',coalesce(max(id),0)) FROM shop_product;
